mapper.select:
SELECT s.*
FROM seat s
         LEFT JOIN reservation r
                   ON r.seat_id = s.id
                       AND r.reserve_date = #{date}
                       AND r.slot_id = #{slotId}
                       AND r.occupy_flag = 1
WHERE s.room_id = #{roomId}
  AND s.status = 1
  AND s.deleted = 0
  AND r.id IS NULL
ORDER BY s.row_num, s.col_num;

SELECT r.id, r.user_id, u.username, r.seat_id, r.room_id, r.reserve_date, r.slot_id, r.status, r.create_time, r.deadline FROM reservation r LEFT JOIN sys_user u ON r.user_id = u.id
AND r.user_id = #{userId} AND r.room_id = #{roomId} AND r.reserve_date = #{reserveDate} AND r.status = #{status}
ORDER BY r.create_time DESC
